import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_add_hardswish_kernel(
    const float* conv_output,
    const float* add_input,
    float* output,
    int num_elements
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float sum = conv_output[idx] + add_input[idx];
        float hs = sum * fminf(fmaxf(sum + 3.0f, 0.0f), 6.0f) / 6.0f;
        output[idx] = sum * hs;
    }
}

torch::Tensor fused_op_cuda(
    torch::Tensor conv_output,
    torch::Tensor add_input
) {
    TORCH_CHECK(conv_output.is_cuda(), "Conv output must be CUDA tensor");
    TORCH_CHECK(add_input.is_cuda(), "Add input must be CUDA tensor");

    auto output = torch::empty_like(conv_output);
    int num_elements = conv_output.numel();

    const int threads = 256;
    int blocks = (num_elements + threads - 1) / threads;

    fused_add_hardswish_kernel<<<blocks, threads>>>(
        conv_output.data_ptr<float>(),
        add_input.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements
    );

    return output;
}
"""

cpp_wrapper = """
torch::Tensor fused_op_cuda(torch::Tensor conv_output, torch::Tensor add_input);
"""

fused_extension = load_inline(
    name='fused_ops',
    cpp_sources=cpp_wrapper,
    cuda_sources=fused_kernel_code,
    functions=['fused_op_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding,
            output_padding=output_padding
        )
        self.bias = nn.Parameter(torch.randn(bias_shape))

    def forward(self, x, add_input):
        x = self.conv_transpose(x)
        x = fused_extension.fused_op_cuda(x, add_input)
        return x
